package com.coraline.tycoon;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.inventory.Slot;
import net.minecraft.world.item.*;
import net.minecraftforge.gametest.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class TycoonFoodGameTests {
    private static ServerPlayer player(GameTestHelper t,boolean personal){var server=t.getLevel().getServer();var p=new ServerPlayer(server,personal?server.getLevel(TycoonWorld.KEY):server.overworld(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"TycoonFoodQA"));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(server,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);TycoonWorld.home(p).state.putBoolean("Activated",true);p.setPos(personal?TycoonWorld.home(p).center().getCenter():t.absolutePos(new BlockPos(2,4,2)).getCenter());return p;}
    private static void clean(ServerPlayer p){TycoonNativePlayers.remove(p);TycoonVisitTickets.release(p.server,TycoonWorld.home(p));TycoonData.get(p.server).homes.remove(p.getUUID());TycoonNetwork.clear(p.getUUID());}
    private static TycoonData.Resident resident(ServerPlayer p){var r=TycoonCare.generate(UUID.randomUUID());r.n.putString("Status","ACTIVE");r.n.putBoolean("DebugChild",true);TycoonDialogue.initialize(r);TycoonWorld.home(p).residents.put(r.id,r);return r;}
    @GameTest(template="empty") public static void actualVanillaFoodPropertiesGiveDistinctCareTiers(GameTestHelper t){
        t.assertTrue(TycoonFoodQuality.tier(new ItemStack(Items.GOLDEN_CARROT))==TycoonFoodQuality.Tier.EXCELLENT,"Golden carrot lost configured excellent tier");t.assertTrue(TycoonFoodQuality.tier(new ItemStack(Items.COOKED_BEEF))==TycoonFoodQuality.Tier.GOOD,"Steak not Good");t.assertTrue(TycoonFoodQuality.tier(new ItemStack(Items.BREAD))==TycoonFoodQuality.Tier.NORMAL,"Bread not Normal");t.assertTrue(TycoonFoodQuality.tier(new ItemStack(Items.POTATO))==TycoonFoodQuality.Tier.POOR,"Potato not Poor");
        var r=TycoonCare.generate(UUID.randomUUID());var carrot=new ItemStack(Items.GOLDEN_CARROT);var steak=new ItemStack(Items.COOKED_BEEF);var bread=new ItemStack(Items.BREAD);t.assertTrue(TycoonFoodQuality.neglect(r,carrot,true)<TycoonFoodQuality.neglect(r,steak,true)&&TycoonFoodQuality.neglect(r,steak,true)<TycoonFoodQuality.neglect(r,bread,true),"Foods have identical care effects");t.assertTrue(TycoonFoodQuality.hunger(steak)>TycoonFoodQuality.hunger(bread),"Nutrition replaced with quality score");t.succeed();
    }
    @GameTest(template="empty") public static void rottenFleshIsWorseThanGoodFoodButBetterThanMissingBothServiceModes(GameTestHelper t){var r=TycoonCare.generate(UUID.randomUUID());r.n.putString("Favorite","minecraft:rotten_flesh");var bad=new ItemStack(Items.ROTTEN_FLESH);t.assertTrue(TycoonBlockEntity.food(bad)&&TycoonFoodQuality.tier(bad)==TycoonFoodQuality.Tier.TERRIBLE,"Rotten flesh must be edible but terrible");for(boolean served:new boolean[]{false,true}){double penalty=TycoonFoodQuality.neglect(r,bad,served);t.assertTrue(penalty>0&&penalty<TycoonFoodConfig.MISSED.get(),"Rotten flesh improves care or is worse than no food");}t.assertTrue(TycoonFoodQuality.neglect(r,new ItemStack(Items.COOKED_BEEF),true)<TycoonFoodQuality.neglect(r,new ItemStack(Items.COOKED_BEEF),false),"Ignoring requests gives a better care reward");r.need("Hunger",0);r.need("Neglect",40);TycoonCare.feed(r,bad,true);t.assertTrue(r.need("Hunger")>0&&r.need("Neglect")>40,"Nutrition/care signs incorrect");t.succeed();}
    @GameTest(template="empty") public static void missedMealPenaltiesAreLoadedActiveEpisodesNotEveryRetry(GameTestHelper t){var p=player(t,false);try{var r=resident(p);r.need("Neglect",40);int count=TycoonFoodConfig.EPISODE.get()/20;for(int i=0;i<count-1;i++)TycoonMeals.missed(p,r,false);t.assertTrue(r.need("Neglect")==40,"Retry applied full episode early");TycoonMeals.missed(p,r,false);t.assertTrue(r.need("Neglect")==40+TycoonFoodConfig.MISSED.get(),"Missed episode not recorded once");TycoonMeals.missed(p,r,false);t.assertTrue(r.n.getInt("MissedMealEpisodes")==1,"Immediate retry repeated penalty");TycoonDialogue.set(r,.4,.5);r.n.putInt("HungryMealTicks",TycoonFoodConfig.EPISODE.get()-20);TycoonMeals.missed(p,r,true);t.assertTrue(Math.abs(TycoonDialogue.trust(r)-(.4-TycoonFoodConfig.OTHER_MISSED.get()))<.000001&&TycoonDialogue.suspicion(r)==.5,"Empty Other Fridge penalty wrong or also applies WorldGoodness");}finally{clean(p);}t.succeed();}
    @GameTest(template="empty") public static void restrictedFridgeRejectsVanillaCakeAndForeignFoodAtServerSlot(GameTestHelper t){var p=player(t,true);try{var at=TycoonWorld.home(p).center().offset(3,0,2);p.serverLevel().getChunkAt(at);TycoonWorld.placeOwned(p.serverLevel(),at,TycoonContent.BLOCKS.get("other_world_fridge").get(),p.getUUID());var be=(TycoonBlockEntity)p.serverLevel().getBlockEntity(at);var good=TycoonFoodContent.owned(p,2,4);var foreign=good.copy();foreign.getTag().putUUID("TycoonOwner",UUID.randomUUID());t.assertTrue(be.canPlaceItem(0,good)&&!be.canPlaceItem(0,new ItemStack(Items.BREAD))&&!be.canPlaceItem(0,new ItemStack(Items.CAKE))&&!be.canPlaceItem(0,TycoonFoodContent.owned(p,7,1))&&!be.canPlaceItem(0,foreign),"Other fridge accepts bypass meals");var menu=new TycoonFridgeMenu(1,p.getInventory(),be);Slot slot=menu.getSlot(0);t.assertTrue(slot.mayPlace(good)&&!slot.mayPlace(new ItemStack(Items.COOKED_BEEF)),"Chest quick-move bypasses filter");be.setItem(0,new ItemStack(Items.BREAD));t.assertTrue(be.getItem(0).isEmpty(),"Direct insertion bypasses restriction");be.setItem(0,good);be.mealDebit=UUID.randomUUID();var saved=be.saveWithFullMetadata();var copy=new TycoonBlockEntity(at,be.getBlockState());copy.load(saved);t.assertTrue(copy.getItem(0).getCount()==4&&p.getUUID().equals(copy.owner)&&be.mealDebit.equals(copy.mealDebit),"Actual stock/owner/debit lost on reload");menu.removed(p);}finally{clean(p);}t.succeed();}
    @GameTest(template="empty") public static void foodShopFailureNeverChargesOrAutoStocks(GameTestHelper t){var p=player(t,true);try{var h=TycoonWorld.home(p);h.state.putLong("SoulEssence",100);for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));String result=TycoonFoodShop.buy(p,2,4);t.assertTrue(result.contains("Free")&&h.state.getLong("SoulEssence")==100&&!h.state.contains("PendingTransaction"),"Full inventory charged Soul Essence");t.assertTrue(TycoonFoodShop.buy(p,7,8).contains("Invalid")&&h.state.getLong("SoulEssence")==100,"Invalid quantity accepted");t.assertFalse(com.coraline.feast.MainStoryRebirth.retireStack(TycoonFoodContent.owned(p,7,1),p.getUUID(),UUID.randomUUID(),0),"Story reset wipes Welcome Home Cake");}finally{clean(p);}t.succeed();}
    @GameTest(template="empty",timeoutTicks=180) public static void actualSoulPurchaseAndManualCakeAreCheckpointedExactlyOnce(GameTestHelper t){
        var p=player(t,true);var h=TycoonWorld.home(p);TycoonWorld.prepare(p);TycoonNativePlayers.add(p);h.state.putLong("SoulEssence",100);var r=resident(p);var visit=new CompoundTag();visit.putUUID("Session",UUID.randomUUID());visit.putString("Phase","INSIDE");visit.putLong("EnteredAt",h.clock());visit.putLong("LeaveAfter",h.clock()+10000);r.n.put("Visit",visit);r.n.putInt("VisitCount",1);r.n.putUUID("FirstVisitSession",visit.getUUID("Session"));TycoonDialogue.set(r,.1,.5);
        var a=TycoonContent.NPC.get().create(p.serverLevel());a.configure(p.getUUID(),r.id,false,r.n.getInt("Appearance"));a.setPos(p.position().add(1,0,0));r.n.putUUID("Entity",a.getUUID());p.serverLevel().addFreshEntity(a);var chunk=new net.minecraft.world.level.ChunkPos(a.blockPosition());p.serverLevel().setChunkForced(chunk.x,chunk.z,true);
        t.runAtTickTime(60,()->{try{t.assertTrue(p.serverLevel().getEntity(a.getUUID())==a,"Canonical gift actor not loaded");String result=TycoonFoodShop.buy(p,7,1);t.assertTrue(result.startsWith("Purchased")&&h.state.getLong("SoulEssence")==20,"Real Soul purchase failed: "+result);var cake=p.getInventory().getItem(0);t.assertTrue(TycoonFoodContent.index(cake)==7&&TycoonWorld.owned(p,cake),"Purchase did not deliver actual bound cake");p.getInventory().selected=0;p.setPos(a.position().add(0,0,1));TycoonDialogue.set(r,.1,.5);t.assertTrue(TycoonWelcomeCake.give(p,a)&&p.getMainHandItem().isEmpty(),"Manual gift failed to debit actual item");for(int i=0;i<6;i++)TycoonWelcomeCake.tick(p,r,a);t.assertTrue(Math.abs(TycoonDialogue.trust(r)-.3)<.000001&&Math.abs(TycoonDialogue.suspicion(r)-.3)<.000001&&r.n.getBoolean("welcome_home_cake_received"),"Cake is not exact+.20/-.20");p.setItemInHand(InteractionHand.MAIN_HAND,TycoonFoodContent.owned(p,7,1));TycoonWelcomeCake.give(p,a);t.assertTrue(p.getMainHandItem().getCount()==1&&Math.abs(TycoonDialogue.trust(r)-.3)<.000001,"Repeated gifting duplicates reward/consumption");t.assertTrue(TycoonCheckpoints.home(p)&&TycoonCheckpoints.player(p),"Gift and consumed inventory do not match saved checkpoint");}catch(java.io.IOException failure){throw new IllegalStateException(failure);}finally{a.discard();p.serverLevel().setChunkForced(chunk.x,chunk.z,false);clean(p);}t.succeed();});
    }
    // Keep wall-clock-sensitive vanilla navigation out of the simultaneous
    // authored-house preparation batch; it can stall the server for minutes.
    @GameTest(template="empty",timeoutTicks=600,batch="tycoon-food-motion") public static void actualVisitorWalksFetchesCarriesSeatsAndConsumesOneServing(GameTestHelper t){
        var p=player(t,true);var l=p.serverLevel();var h=TycoonWorld.home(p);TycoonWorld.prepare(p);TycoonNativePlayers.add(p);h.state.putLong("ActiveTicks",1000);var c=h.center();var chunk=new net.minecraft.world.level.ChunkPos(c);l.setChunkForced(chunk.x,chunk.z,true);l.setChunkForced(chunk.x-1,chunk.z,true);l.setChunkForced(chunk.x,chunk.z-1,true);l.setChunkForced(chunk.x-1,chunk.z-1,true);
        var table=c.offset(-2,0,2);var source=c.offset(2,0,2);for(var entry:Map.of(table,"other_world_supper_table",source,"other_world_fridge").entrySet()){TycoonWorld.placeOwned(l,entry.getKey(),TycoonContent.BLOCKS.get(entry.getValue()).get(),p.getUUID());var f=h.state.getCompound("OtherFurniture");f.putString(Long.toString(entry.getKey().asLong()),entry.getValue());h.state.put("OtherFurniture",f);}var be=(TycoonBlockEntity)l.getBlockEntity(source);be.setItem(0,TycoonFoodContent.owned(p,0,2));
        var r=resident(p);r.need("Hunger",40);TycoonDialogue.set(r,.2,.5);var v=new CompoundTag();v.putString("Phase","INSIDE");v.putLong("LeaveAfter",10000);r.n.put("Visit",v);var a=TycoonContent.NPC.get().create(l);a.configure(p.getUUID(),r.id,false,1);a.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(c.offset(-2,0,0)));r.n.putUUID("Entity",a.getUUID());l.addFreshEntity(a);int[] elapsed={0};boolean[] observed={false,false};double[] beforeMeal={Double.NaN};double reward=TycoonFoodConfig.TRUST[0].get()*TycoonFoodQuality.preference(r,be.getItem(0));
        Runnable cleanup=()->{a.stopRiding();a.discard();l.setChunkForced(chunk.x,chunk.z,false);l.setChunkForced(chunk.x-1,chunk.z,false);l.setChunkForced(chunk.x,chunk.z-1,false);l.setChunkForced(chunk.x-1,chunk.z-1,false);clean(p);};
        t.onEachTick(()->{try{int time=++elapsed[0];h.state.putLong("ActiveTicks",1000+time);observed[0]|=r.n.getCompound("Meal").getString("Status").equals("CARRYING");observed[1]|=a.getVehicle() instanceof TycoonSupperSeat;
            if(r.n.contains("Meal")&&!r.n.hasUUID("LastMealReceipt"))beforeMeal[0]=TycoonDialogue.trust(r);
            if(time>40&&time%20==0){if(!TycoonMeals.carryToTable(p,r,a)&&!TycoonMeals.tick(p,r,a))TycoonMeals.otherWorld(p,r,a);}
            if(r.n.hasUUID("LastMealReceipt")){t.assertTrue(observed[0]&&observed[1],"Actual motion skipped carry/seat phases");t.assertTrue(be.getItem(0).getCount()==1&&r.need("Hunger")>55,"Serving consumed incorrectly");t.assertTrue(Double.isFinite(beforeMeal[0])&&Math.abs(TycoonDialogue.trust(r)-(beforeMeal[0]+reward))<.000001,"Meal relationship not exact once: before="+beforeMeal[0]+" reward="+reward+" actual="+TycoonDialogue.trust(r));cleanup.run();t.succeed();}
            else if(time>=570){cleanup.run();t.fail("Real supper route failed at "+a.position()+" / "+r.n.getString("Task")+" / "+r.n.getCompound("Meal"));}
        }catch(Throwable e){cleanup.run();throw e;}});
    }
    @GameTest(template="empty") public static void unresolvedMealReservationDoesNotHoldVisitorDeparture(GameTestHelper t){var p=player(t,true);try{var r=resident(p);r.need("Hunger",10);var v=new CompoundTag();v.putString("Phase","INSIDE");v.putLong("LeaveAfter",10000);r.n.put("Visit",v);var n=new CompoundTag();n.putUUID("Id",UUID.randomUUID());n.putString("Status","RESERVING");n.putBoolean("Personal",true);n.putString("Dimension","minecraft:the_nether");n.putLong("Source",new BlockPos(0,280,0).asLong());n.put("Food",TycoonFoodContent.owned(p,0,1).save(new CompoundTag()));r.n.put("Meal",n);var a=TycoonContent.NPC.get().create(p.serverLevel());a.configure(p.getUUID(),r.id,false,1);a.setPos(p.position());r.n.putUUID("Entity",a.getUUID());t.assertFalse(TycoonMeals.tick(p,r,a),"Uncertain stock escrow captured the AI forever");TycoonVisits.actorTick(p,r,a);t.assertTrue(r.n.getCompound("Visit").getString("Phase").equals("LEAVING")&&r.n.contains("Meal")&&!r.n.hasUUID("LastMealReceipt"),"Recovery fabricated a reward or prevented return home");}finally{clean(p);}t.succeed();}
    @GameTest(template="empty") public static void cakeGiftClampsAndFirstVisitHistorySurvivesReload(GameTestHelper t){var p=player(t,true);try{var r=resident(p);var a=TycoonContent.NPC.get().create(p.serverLevel());a.configure(p.getUUID(),r.id,false,1);var gift=new CompoundTag();gift.putUUID("Receipt",UUID.randomUUID());gift.putInt("Progress",100);gift.put("Item",TycoonFoodContent.owned(p,7,1).save(new CompoundTag()));r.n.put("CakeGift",gift);r.n.putInt("VisitCount",2);r.n.putBoolean("FirstVisitEnded",true);TycoonDialogue.set(r,.9,.1);TycoonWelcomeCake.tick(p,r,a);t.assertTrue(TycoonDialogue.trust(r)==1&&TycoonDialogue.suspicion(r)==0,"Cake clamp wrong");var restored=TycoonData.load(TycoonData.get(p.server).save(new CompoundTag())).home(p.getUUID()).residents.get(r.id);t.assertTrue(restored.n.getBoolean("welcome_home_cake_received")&&restored.n.getBoolean("FirstVisitEnded")&&restored.n.getInt("VisitCount")==2&&!TycoonWelcomeCake.eligible(p,restored),"Reload reopens later visit cake eligibility");}finally{clean(p);}t.succeed();}
    @GameTest(template="empty") public static void starterAndSessionSoulCreditsAreBoundedAndNotResetFarming(GameTestHelper t){var p=player(t,true);try{var h=TycoonWorld.home(p);var r=resident(p);r.n.putBoolean("DebugChild",false);r.n.putInt("VisitCount",1);var v=new CompoundTag();v.putUUID("Session",UUID.randomUUID());v.putLong("EnteredAt",1);r.n.put("Visit",v);h.state.putLong("ActiveTicks",3000);TycoonFoodShop.firstEntry(p,r);TycoonFoodShop.firstEntry(p,r);t.assertTrue(h.state.getLong("SoulEssence")==TycoonFoodConfig.STARTER.get(),"Starter can be farmed by re-entry");TycoonFoodShop.completed(p,r);long credited=h.state.getLong("SoulEssence");TycoonFoodShop.completed(p,r);t.assertTrue(credited==TycoonFoodConfig.STARTER.get()+TycoonFoodConfig.SESSION_REWARD.get()&&h.state.getLong("SoulEssence")==credited,"Visit receipt duplicates credit");r.need("Neglect",90);h.state.putLong("ActiveTicks",30000);v.putUUID("Session",UUID.randomUUID());v.putLong("EnteredAt",1);TycoonFoodShop.completed(p,r);t.assertTrue(h.state.getLong("SoulEssence")==credited,"Neglect generates Soul profit");}finally{clean(p);}t.succeed();}
}
